#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int bitCount(int n) {
        int count = 0;
        while (n) {
            n &= (n - 1);
            count++;
        }
        return count;
    }

    vector<int> sortByBits(vector<int>& arr) {
        sort(arr.begin(), arr.end(), [&](int a, int b) {
            int ba = bitCount(a), bb = bitCount(b);
            return ba == bb ? a < b : ba < bb;
        });
        return arr;
    }
};
